@Composable
private fun LineChartItem(
    data: List<ChartDataPoint>,
    modifier: Modifier = Modifier,
    style: ProgressionChartStyle,
    animate: Boolean,
    animateToProgress: Float,
    interactive: Boolean,
    showTooltip: Boolean,
) {
    if (data.isEmpty()) return

    val targetProgress = animateToProgress.coerceIn(0f, 1f)

    // Animation progress (0.0 to targetProgress)
    val animationProgress = remember { Animatable(if (animate) 0f else targetProgress) }

    // User-controlled progress via tap/drag
    var userProgress by remember { mutableFloatStateOf(-1f) }
    var selectedPoint by remember { mutableStateOf<SelectedChartPoint?>(null) }
    var isDragging by remember { mutableStateOf(false) }

    val density = LocalDensity.current

    LaunchedEffect(animate, data, targetProgress) {
        if (animate && userProgress < 0f) {
            animationProgress.snapTo(0f)
            animationProgress.animateTo(
                targetValue = targetProgress,
                animationSpec = tween(
                    durationMillis = (style.animationDurationMs * targetProgress).toInt(),
                    easing = FastOutSlowInEasing,
                ),
            )
        } else if (!animate) {
            animationProgress.snapTo(targetProgress)
        }
    }

    // Use user progress if set, otherwise use animation progress
    val currentProgress = if (userProgress >= 0f) userProgress else animationProgress.value

    // Helper function to update selection
    fun updateSelection(
        tapX: Float,
        width: Float,
        height: Float,
    ) {
        val tapProgress = (tapX / width).coerceIn(0f, 1f)

        val minValue = data.minOf { it.value }
        val maxValue = data.maxOf { it.value }
        val valueRange = maxValue - minValue

        val dataPoints = data.mapIndexed { index, point ->
            val x = if (data.size == 1) {
                width / 2
            } else {
                (index.toFloat() / (data.size - 1)) * width
            }
            val normalizedValue = if (valueRange > 0) {
                (point.value - minValue) / valueRange
            } else {
                0.5f
            }
            val y = height * (1 - normalizedValue)
            Offset(x, y)
        }

        if (dataPoints.size >= 2) {
            val fullPath = buildSmoothPath(dataPoints)
            val pointOnPath = getPointAtProgress(fullPath, tapProgress)

            val closestIndex = findClosestDataPointIndex(tapProgress, data.size)
            val closestData = data[closestIndex]
            val interpolatedValue = interpolateValueAtProgress(data, tapProgress)

            userProgress = tapProgress
            selectedPoint = SelectedChartPoint(
                label = closestData.label,
                value = interpolatedValue,
                progress = tapProgress,
                screenPosition = pointOnPath,
            )
        }
    }

    Box(modifier = modifier) {
        // Main chart canvas
        Box(
            modifier = Modifier
                .matchParentSize()
                .pointerInput(data, interactive) {
                    if (!interactive) return@pointerInput
                    detectTapGestures { tapOffset ->
                        updateSelection(
                            tapX = tapOffset.x,
                            width = size.width.toFloat(),
                            height = size.height.toFloat(),
                        )
                    }
                }
                .pointerInput(data, interactive) {
                    if (!interactive) return@pointerInput
                    detectDragGestures(
                        onDragStart = { offset ->
                            isDragging = true
                            updateSelection(
                                tapX = offset.x,
                                width = size.width.toFloat(),
                                height = size.height.toFloat(),
                            )
                        },
                        onDragEnd = {
                            isDragging = false
                        },
                        onDragCancel = {
                            isDragging = false
                        },
                        onDrag = { change, _ ->
                            change.consume()
                            updateSelection(
                                tapX = change.position.x,
                                width = size.width.toFloat(),
                                height = size.height.toFloat(),
                            )
                        },
                    )
                }
                .drawWithContent {
                    val width = size.width
                    val height = size.height

                    // Grid lines
                    for (i in 1..style.gridLines) {
                        val y = height * (i.toFloat() / (style.gridLines + 1))
                        drawLine(
                            color = style.gridColor,
                            start = Offset(0f, y),
                            end = Offset(width, y),
                            strokeWidth = 1.dp.toPx(),
                            pathEffect = PathEffect.dashPathEffect(floatArrayOf(8f, 8f)),
                        )
                    }

                    val minValue = data.minOf { it.value }
                    val maxValue = data.maxOf { it.value }
                    val valueRange = maxValue - minValue

                    val dataPoints = data.mapIndexed { index, point ->
                        val x = if (data.size == 1) {
                            width / 2
                        } else {
                            (index.toFloat() / (data.size - 1)) * width
                        }
                        val normalizedValue = if (valueRange > 0) {
                            (point.value - minValue) / valueRange
                        } else {
                            0.5f
                        }
                        val y = height * (1 - normalizedValue)
                        Offset(x, y)
                    }

                    if (dataPoints.size < 2) {
                        drawContent()
                        return@drawWithContent
                    }

                    val fullPath = buildSmoothPath(dataPoints)

                    // 1. Draw guide line (full path in neutral color)
                    if (style.showGuideLine) {
                        drawPath(
                            path = fullPath,
                            color = style.guideLineColor,
                            style = Stroke(
                                width = style.guideLineWidth.toPx(),
                                cap = StrokeCap.Round,
                                join = StrokeJoin.Round,
                            ),
                        )
                    }

                    // 2. Draw animated/interactive colored line on top
                    val animatedPath = getAnimatedPath(fullPath, currentProgress)

                    // Gradient fill (animated)
                    if (style.showGradient && currentProgress > 0f) {
                        drawAnimatedGradient(
                            fullPath = fullPath,
                            progress = currentProgress,
                            height = height,
                            firstX = dataPoints.first().x,
                            lineColor = style.lineColor,
                        )
                    }

                    // Main colored line
                    if (currentProgress > 0f) {
                        drawPath(
                            path = animatedPath,
                            color = style.lineColor,
                            style = Stroke(
                                width = style.lineWidth.toPx(),
                                cap = StrokeCap.Round,
                                join = StrokeJoin.Round,
                            ),
                        )
                    }

                    // Animated point that follows the line
                    if (currentProgress > 0f) {
                        val currentPoint = getPointAtProgress(fullPath, currentProgress)

                        // Glow behind point
                        drawCircle(
                            color = style.lineColor.copy(alpha = 0.3f),
                            radius = 12.dp.toPx(),
                            center = currentPoint,
                        )

                        // Outer ring
                        drawCircle(
                            color = style.lineColor,
                            radius = 8.dp.toPx(),
                            center = currentPoint,
                        )

                        // Inner dot
                        drawCircle(
                            color = Color.White,
                            radius = 4.dp.toPx(),
                            center = currentPoint,
                        )
                    }

                    drawContent()
                },
        )

        // Glow layer (behind everything)
        if (style.showGlow && currentProgress > 0f) {
            Box(
                modifier = Modifier
                    .matchParentSize()
                    .blur(12.dp)
                    .drawBehind {
                        val width = size.width
                        val height = size.height

                        val minValue = data.minOf { it.value }
                        val maxValue = data.maxOf { it.value }
                        val valueRange = maxValue - minValue

                        val dataPoints = data.mapIndexed { index, point ->
                            val x = if (data.size == 1) {
                                width / 2
                            } else {
                                (index.toFloat() / (data.size - 1)) * width
                            }
                            val normalizedValue = if (valueRange > 0) {
                                (point.value - minValue) / valueRange
                            } else {
                                0.5f
                            }
                            val y = height * (1 - normalizedValue)
                            Offset(x, y)
                        }

                        if (dataPoints.size >= 2) {
                            val fullPath = buildSmoothPath(dataPoints)
                            val animatedPath = getAnimatedPath(fullPath, currentProgress)

                            drawPath(
                                path = animatedPath,
                                color = style.lineColor.copy(alpha = style.glowAlpha),
                                style = Stroke(
                                    width = style.lineWidth.toPx() * 4,
                                    cap = StrokeCap.Round,
                                    join = StrokeJoin.Round,
                                ),
                            )
                        }
                    },
            )
        }

        // Tooltip for selected point
        if (showTooltip && selectedPoint != null) {
            val point = selectedPoint!!
            val tooltipOffsetX = with(density) { point.screenPosition.x.toDp() - 40.dp }
            val tooltipOffsetY = with(density) { point.screenPosition.y.toDp() - 70.dp }

            Box(
                modifier = Modifier
                    .offset(x = tooltipOffsetX, y = tooltipOffsetY)
                    .background(
                        color = ProgressionGlowColors.TooltipBackground,
                        shape = RoundedCornerShape(8.dp),
                    )
                    .drawBehind {
                        drawRoundRect(
                            color = style.lineColor,
                            style = Stroke(width = 2f),
                            cornerRadius = CornerRadius(8.dp.toPx()),
                        )
                    }
                    .padding(horizontal = 12.dp, vertical = 8.dp),
            ) {
                Column(horizontalAlignment = Alignment.CenterHorizontally) {
                    Text(
                        text = point.label,
                        fontSize = 10.sp,
                        color = ProgressionGlowColors.TextSecondary,
                    )
                    Text(
                        text = "${point.value.toInt()}",
                        fontSize = 16.sp,
                        fontWeight = FontWeight.Bold,
                        color = style.lineColor,
                    )
                }
            }
        }
    }
}

@Composable
private fun HourlyTabConfigEditor(
    config: List<HourlyTabConfigItem>,
    onConfigChange: (List<HourlyTabConfigItem>) -> Unit,
) {
    var items by remember { mutableStateOf(config) }
    val density = LocalDensity.current
    val rowHeightPx = with(density) { 56.dp.toPx() }
    var draggingIndex by remember { mutableIntStateOf(-1) }
    var dragOffsetY by remember { mutableFloatStateOf(0f) }
    LaunchedEffect(config) {
        if (draggingIndex < 0 && config != items) items = config
    }

    fun commit(next: List<HourlyTabConfigItem>) {
        items = next
        onConfigChange(next)
    }

    fun move(from: Int, to: Int) {
        if (from == to || from !in items.indices || to !in items.indices) return
        val next = items.toMutableList()
        val item = next.removeAt(from)
        next.add(to, item)
        commit(next)
    }

    fun setEnabled(id: String, enabled: Boolean) {
        val index = items.indexOfFirst { it.id == id }
        if (index < 0) return
        // Keep at least one tab enabled
        if (!enabled && items.count { it.enabled } <= 1 && items[index].enabled) return
        val next = items.toMutableList()
        next[index] = next[index].copy(enabled = enabled)
        commit(next)
    }

    Column(verticalArrangement = Arrangement.spacedBy(6.dp)) {
        items.forEach { item ->
            key(item.id) {
                val index = items.indexOfFirst { it.id == item.id }
                val isDragging = index == draggingIndex
                val source = hourlyTabSourceStyle(item.id)
                val accent = if (item.enabled) source.accent else source.accent.copy(alpha = 0.35f)
                Row(
                    Modifier
                        .fillMaxWidth()
                        .zIndex(if (isDragging) 1f else 0f)
                        .offset {
                            IntOffset(
                                x = 0,
                                y = if (isDragging) dragOffsetY.roundToInt() else 0,
                            )
                        }
                        .clip(RoundedCornerShape(8.dp))
                        .background(
                            when {
                                isDragging -> Color(0xFF37474F)
                                !item.enabled -> Color(0xFF1A2226)
                                else -> SurfaceDark
                            },
                        )
                        .border(
                            width = 1.dp,
                            color = accent.copy(alpha = if (item.enabled) 0.45f else 0.2f),
                            shape = RoundedCornerShape(8.dp),
                        )
                        // Stable key — do NOT depend on index/items or the gesture cancels on swap
                        .pointerInput(Unit) {
                            detectDragGesturesAfterLongPress(
                                onDragStart = {
                                    val idx = items.indexOfFirst { it.id == item.id }
                                    if (idx < 0) return@detectDragGesturesAfterLongPress
                                    draggingIndex = idx
                                    dragOffsetY = 0f
                                },
                                onDragCancel = {
                                    draggingIndex = -1
                                    dragOffsetY = 0f
                                },
                                onDragEnd = {
                                    draggingIndex = -1
                                    dragOffsetY = 0f
                                },
                                onDrag = { change, dragAmount ->
                                    change.consume()
                                    val from = draggingIndex
                                    if (from < 0) return@detectDragGesturesAfterLongPress
                                    dragOffsetY += dragAmount.y
                                    val shift = (dragOffsetY / rowHeightPx).toInt()
                                    if (shift != 0) {
                                        val to = (from + shift).coerceIn(0, items.lastIndex)
                                        if (to != from) {
                                            val next = items.toMutableList()
                                            val moved = next.removeAt(from)
                                            next.add(to, moved)
                                            items = next
                                            onConfigChange(next)
                                            draggingIndex = to
                                            dragOffsetY -= shift * rowHeightPx
                                        }
                                    }
                                },
                            )
                        }
                        .padding(end = 6.dp, top = 2.dp, bottom = 2.dp),
                    verticalAlignment = Alignment.CenterVertically,
                ) {
                    Box(
                        Modifier
                            .width(4.dp)
                            .height(48.dp)
                            .background(accent),
                    )
                    Icon(
                        Icons.Filled.DragHandle,
                        contentDescription = "Drag to reorder",
                        tint = OnSurfaceMuted,
                        modifier = Modifier
                            .padding(start = 6.dp)
                            .size(22.dp),
                    )
                    Column(
                        Modifier
                            .weight(1f)
                            .padding(horizontal = 8.dp),
                    ) {
                        Text(
                            text = PreferencesRepository.hourlyTabDisplayName(item.id),
                            color = if (item.enabled) Color.White else OnSurfaceMuted,
                            fontSize = 15.sp,
                        )
                        Text(
                            text = source.shortLabel,
                            color = accent,
                            fontSize = 11.sp,
                            fontWeight = FontWeight.Medium,
                        )
                    }
                    IconButton(
                        onClick = { move(index, index - 1) },
                        enabled = index > 0,
                        modifier = Modifier.size(34.dp),
                    ) {
                        Icon(
                            Icons.Filled.KeyboardArrowUp,
                            contentDescription = "Move up",
                            tint = if (index > 0) Color.White else Color(0xFF546E7A),
                        )
                    }
                    IconButton(
                        onClick = { move(index, index + 1) },
                        enabled = index >= 0 && index < items.lastIndex,
                        modifier = Modifier.size(34.dp),
                    ) {
                        Icon(
                            Icons.Filled.KeyboardArrowDown,
                            contentDescription = "Move down",
                            tint = if (index >= 0 && index < items.lastIndex) {
                                Color.White
                            } else {
                                Color(0xFF546E7A)
                            },
                        )
                    }
                    Switch(
                        checked = item.enabled,
                        onCheckedChange = { setEnabled(item.id, it) },
                    )
                }
            }
        }
    }
}

@Composable
private fun NetworkingHeroCard(
    effectiveUrl: String,
    localActive: Boolean,
    autoUrlSwitch: Boolean,
    onToggleAuto: (Boolean) -> Unit
) {
    Column(
        modifier = Modifier
            .fillMaxWidth()
            .padding(horizontal = 16.dp, vertical = 8.dp)
            .clip(RoundedCornerShape(28.dp))
            .background(MaterialTheme.colorScheme.surfaceContainer)
            .padding(20.dp),
        verticalArrangement = Arrangement.spacedBy(20.dp)
    ) {
        // Active address headline
        Row(verticalAlignment = Alignment.CenterVertically) {
            Icon(
                imageVector = if (localActive) Icons.Outlined.Wifi else Icons.Outlined.Public,
                contentDescription = null,
                tint = MaterialTheme.colorScheme.primary,
                modifier = Modifier.size(22.dp)
            )
            Spacer(Modifier.width(12.dp))
            Column(modifier = Modifier.weight(1f)) {
                Text(
                    text = stringResource(R.string.cloud_net_connection),
