@OptIn(ExperimentalGlideComposeApi::class, ExperimentalMaterial3Api::class)
@Composable
fun ProfileCard(
    thumbnailUrl: String,
    iconUrl: String,
    displayName: String,
    statusDescription: String,
    trustRankColor: Color,
    statusColor: Color,
    tags: List<String>,
    badges: List<Badge>,
    pronouns: String,
    ageVerificationStatus: String,
    disablePeek: Boolean = true,
    onPeek: (url: String) -> Unit
) {
    ElevatedCard(
        elevation = CardDefaults.cardElevation(
            defaultElevation = 6.dp
        ),
        modifier = Modifier
            .height(270.dp)
            .widthIn(0.dp, 520.dp)
            .fillMaxWidth()
    ) {
        Column(
            verticalArrangement = Arrangement.spacedBy((-50).dp),
            modifier = Modifier.fillMaxSize()
        ) {
            GlideImage(
                model = thumbnailUrl,
                contentDescription = null,
                modifier = Modifier
                    .fillMaxWidth()
                    .height(160.dp)
                    .clickableIf(
                        enabled = !disablePeek,
                        onClick = {
                            onPeek(thumbnailUrl)
                        }),
                contentScale = ContentScale.Crop,
                loading = placeholder(R.drawable.image_placeholder),
                failure = placeholder(R.drawable.image_placeholder)
            )

            Column(
                modifier = Modifier.padding(start = 16.dp)
            ) {
                Badge(
                    containerColor = MaterialTheme.colorScheme.surfaceContainerHighest,
                    modifier = Modifier
                        .size(80.dp)
                        .align(Alignment.CenterHorizontally)
                        .clickableIf(
                            enabled = !disablePeek,
                            onClick = {
                                onPeek(iconUrl)
                            })
                ) {
                    GlideImage(
                        model = iconUrl,
                        contentDescription = null,
                        modifier = Modifier
                            .size(72.dp)
                            .clip(RoundedCornerShape(50)),
                        contentScale = ContentScale.Crop,
                        alignment = Alignment.Center,
                        loading = placeholder(R.drawable.image_placeholder),
                        failure = placeholder(R.drawable.image_placeholder)
                    )
                }
            }

            Row {
                Row(
                    modifier = Modifier.padding(start = 12.dp, top = 60.dp),
                    verticalAlignment = Alignment.CenterVertically,
                    horizontalArrangement = Arrangement.Start
                ) {
                    Text(
                        text = displayName,
                        style = MaterialTheme.typography.titleLarge,
                        fontWeight = FontWeight.SemiBold,
                        textAlign = TextAlign.Left,
                        color = trustRankColor,
                        maxLines = 1,
                        overflow = TextOverflow.Ellipsis,
                    )
                    if (ageVerificationStatus == "18+") {
                        Badge(
                            containerColor = Color(0xFF606FE4),
                            modifier = Modifier.padding(start = 8.dp)
                        ) {
                            Text(
                                modifier = Modifier.padding(2.dp),
                                text = "18+",
                                fontSize = 12.sp,
                                fontWeight = FontWeight.Bold,
                                textAlign = TextAlign.Left,
                                maxLines = 1,
                                overflow = TextOverflow.Ellipsis,
                                color = Color.White
                            )
                        }
                    }
                    if (pronouns.isNotEmpty()) {
                        Badge(
                            containerColor = MaterialTheme.colorScheme.secondary,
                            modifier = Modifier.padding(start = 8.dp)
                        ) {
                            Text(
                                modifier = Modifier.padding(2.dp).widthIn(Dp.Unspecified, 128.dp),
                                text = pronouns,
                                fontSize = 12.sp,
                                fontWeight = FontWeight.Bold,
                                textAlign = TextAlign.Left,
                                maxLines = 1,
                                overflow = TextOverflow.Ellipsis,
                            )
                        }
                    }
                }

                Row(
                    modifier = Modifier
                        .fillMaxWidth()
                        .padding(end = 4.dp),
                    horizontalArrangement = Arrangement.End
                ) {
                    Languages(languages = tags, modifier = Modifier.padding(top = 8.dp))
                }
            }

            Row(
                modifier = Modifier.padding(start = 12.dp, top = 50.dp),
                horizontalArrangement = Arrangement.Start
            ) {
                Row(
                    verticalAlignment = Alignment.CenterVertically
                ) {
                    Badge(containerColor = statusColor, modifier = Modifier.size(16.dp))
                    Text(
                        modifier = Modifier.padding(start = 8.dp),
                        text = statusDescription,
                        textAlign = TextAlign.Left,
                        fontWeight = FontWeight.SemiBold,
                        overflow = TextOverflow.Ellipsis,
                        maxLines = 1
                    )
                }

                Row(
                    modifier = Modifier
                        .fillMaxWidth()
                        .padding(end = 8.dp),
                    horizontalArrangement = Arrangement.End
                ) {
                    for (badge in badges) {
                        TooltipBox(
                            positionProvider = TooltipDefaults.rememberPlainTooltipPositionProvider(),
                            tooltip = {
                                PlainTooltip {
                                    Text("${badge.badgeName} (${if (badge.showcased) { "Showcased" } else { "Hidden" }})")
                                }
                            },
                            state = rememberTooltipState()
                        ) {
                            GlideImage(
                                model = badge.badgeImageUrl,
                                contentDescription = null,
                                modifier = Modifier
                                    .size(28.dp)
                                    .padding(2.dp),
                                alpha = if (badge.showcased) { 1.0f } else { 0.5f }
                            )
                        }
                    }
                }
            }
        }
    }
}

@Composable
private fun ChapterDropdown(
	chapters: List<OutlineChapter>,
	activeChapterIndex: Int,
	onJumpTo: (Int) -> Unit,
) {
	var expanded by remember { mutableStateOf(false) }
	val rotation by animateFloatAsState(
		targetValue = if (expanded) 180f else 0f,
		label = "outlineChapterDropdownRotation",
	)
	val current = chapters.getOrNull(activeChapterIndex)

	Column(modifier = Modifier.fillMaxWidth()) {
		Row(
			modifier = Modifier
				.fillMaxWidth()
				.background(MaterialTheme.colorScheme.surfaceContainerLow)
				.clickable { expanded = !expanded }
				.padding(horizontal = Ui.Padding.XL, vertical = Ui.Padding.L),
			verticalAlignment = Alignment.CenterVertically,
			horizontalArrangement = Arrangement.spacedBy(Ui.Padding.L),
		) {
			HdMonoLabel(text = Res.string.scene_list_outline_overview_jump_to.get())
			Row(
				modifier = Modifier.weight(1f),
				verticalAlignment = Alignment.Bottom,
				horizontalArrangement = Arrangement.spacedBy(Ui.Padding.M),
			) {
				Text(
					text = romanNumeral(activeChapterIndex + 1),
					style = MaterialTheme.typography.titleMedium,
					fontWeight = FontWeight.Light,
					color = MaterialTheme.colorScheme.onSurfaceVariant,
				)
				Text(
					text = current?.chapter?.sceneItem?.name ?: untitledChapter(),
					style = MaterialTheme.typography.titleMedium,
					fontWeight = FontWeight.Medium,
					color = MaterialTheme.colorScheme.onSurface,
					maxLines = 1,
					overflow = TextOverflow.Ellipsis,
				)
			}
			HdMonoLabel(
				text = Res.string.scene_list_outline_overview_position.get(
					activeChapterIndex + 1,
					chapters.size,
				),
			)
			Icon(
				imageVector = Icons.Default.KeyboardArrowDown,
				contentDescription = null,
				tint = MaterialTheme.colorScheme.onSurfaceVariant,
				modifier = Modifier
					.size(20.dp)
					.rotate(rotation),
			)
		}
		HorizontalDivider(
			thickness = Dp.Hairline,
			color = MaterialTheme.colorScheme.outlineVariant,
		)

		AnimatedVisibility(
			visible = expanded,
			enter = expandVertically() + fadeIn(),
			exit = shrinkVertically() + fadeOut(),
		) {
			Column(
				modifier = Modifier
					.fillMaxWidth()
					.heightIn(max = 320.dp)
					.background(MaterialTheme.colorScheme.surface),
			) {
				LazyColumn(modifier = Modifier.fillMaxWidth()) {
					itemsIndexed(chapters, key = { idx, _ -> "drop-$idx" }) { idx, ch ->
						ChapterRailItem(
							index = idx,
							chapter = ch,
							selected = idx == activeChapterIndex,
							onClick = {
								onJumpTo(idx)
								expanded = false
							},
						)
						HorizontalDivider(
							thickness = Dp.Hairline,
							color = MaterialTheme.colorScheme.outlineVariant,
						)
					}
				}
			}
		}
	}
}

